import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'

type LoadingKind = 'page' | 'route'

type PlatformLoadingContextValue = {
  register: (id: string, kind: LoadingKind, label: string) => void
  unregister: (id: string) => void
  overlayLabel: string | null
}

const PlatformLoadingContext = createContext<PlatformLoadingContextValue | null>(null)

const DEFAULT_ROUTE_LOADING_DELAY_MS = 175

/** Dev diagnostic: trace loader register/unregister and warn when overlays stack. */
function logLoaders(
  action: 'register' | 'unregister',
  id: string,
  page: Map<string, string>,
  route: Map<string, string>,
): void {
  if (!import.meta.env.DEV) return
  const total = page.size + route.size
  const snapshot = {
    id,
    total,
    page: Array.from(page.values()),
    route: Array.from(route.values()),
  }
  if (total > 1) {
    console.warn(
      `[PlatformLoading] ${action} ΓåÆ ${total} concurrent loaders (possible stacked overlay)`,
      snapshot,
    )
  } else {
    console.debug(`[PlatformLoading] ${action} ΓåÆ ${total} active`, snapshot)
  }
}

function resolveLabel(page: Map<string, string>, route: Map<string, string>): string | null {
  if (page.size > 0) {
    return Array.from(page.values()).pop() ?? null
  }
  if (route.size > 0) {
    return Array.from(route.values()).pop() ?? null
  }
  return null
}

export function PlatformLoadingProvider({ children }: { children: ReactNode }) {
  const pageLoaders = useRef(new Map<string, string>())
  const routeLoaders = useRef(new Map<string, string>())
  const [overlayLabel, setOverlayLabel] = useState<string | null>(null)

  const recompute = useCallback(() => {
    setOverlayLabel(resolveLabel(pageLoaders.current, routeLoaders.current))
  }, [])

  const register = useCallback(
    (id: string, kind: LoadingKind, label: string) => {
      const target = kind === 'page' ? pageLoaders.current : routeLoaders.current
      target.set(id, label)
      logLoaders('register', id, pageLoaders.current, routeLoaders.current)
      recompute()
    },
    [recompute],
  )

  const unregister = useCallback(
    (id: string) => {
      pageLoaders.current.delete(id)
      routeLoaders.current.delete(id)
      logLoaders('unregister', id, pageLoaders.current, routeLoaders.current)
      recompute()
    },
    [recompute],
  )

  const value = useMemo(
    () => ({ register, unregister, overlayLabel }),
    [register, unregister, overlayLabel],
  )

  return <PlatformLoadingContext.Provider value={value}>{children}</PlatformLoadingContext.Provider>
}

function usePlatformLoadingContext(): PlatformLoadingContextValue {
  const context = useContext(PlatformLoadingContext)
  if (!context) {
    throw new Error('Platform loading hooks must be used within PlatformLoadingProvider')
  }
  return context
}

function useLoadingLabel(kind: LoadingKind, label: string | null | false): void {
  const { register, unregister } = usePlatformLoadingContext()
  const id = useId()
  const nextLabel = label || null

  useLayoutEffect(() => {
    if (nextLabel) {
      register(id, kind, nextLabel)
    } else {
      unregister(id)
    }
    return () => {
      unregister(id)
    }
  }, [id, kind, nextLabel, register, unregister])
}

/** Report page data loading to AppLayout overlay. */
export function usePlatformLoading(label: string | null | false): void {
  useLoadingLabel('page', label)
}

/** Report lazy route chunk loading to AppLayout overlay. */
export function useRouteLoading(label: string | null | false): void {
  useLoadingLabel('route', label)
}

/** Delay route overlay to avoid flash when lazy chunks are already cached. */
export function useDelayedRouteLoading(
  label: string,
  delayMs = DEFAULT_ROUTE_LOADING_DELAY_MS,
): void {
  const [showLabel, setShowLabel] = useState(false)

  useEffect(() => {
    const timer = window.setTimeout(() => setShowLabel(true), delayMs)
    return () => {
      clearTimeout(timer)
      setShowLabel(false)
    }
  }, [delayMs, label])

  useRouteLoading(showLabel ? label : null)
}

/** Single overlay label ΓÇö updates in the same layout pass as loaders register/clear. */
export function usePlatformOverlayLabel(): string | null {
  return usePlatformLoadingContext().overlayLabel
}

/** Alias of overlay label ΓÇö embed `content-ready` must not wait on a hide linger. */
export function usePlatformActiveLabel(): string | null {
  return usePlatformLoadingContext().overlayLabel
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { ChevronLeft, ChevronRight, Save } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { normalizeLocale } from '@webonone/i18n'
import type { MediaItemDto } from '@webonone/media-embed'
import {
  PLATFORM_EMBED_QUERY,
  resolvePlatformEmbedParentOrigin,
  sendPlatformPeerDialogBusy,
  usePlatformPeerDialogSubmit,
  useRequestPlatformPeerDialog,
} from '@webonone/platform-embed'
import {
  Alert,
  AlertDescription,
  Button,
  CustomDialog,
  formatPhoneE164,
  getBrowserDefaultCountryIso2,
  mapZodIssuesToFieldErrors,
  parsePhoneE164,
} from '@webonone/ui-kit'
import { useAppDispatch, useAppSelector } from '@/app/store/hooks'
import { authActions } from '@/features/auth/store'
import { isAllowedParentOrigin } from '@/features/shell/utils/platformConfig'
import { changeAppLocale } from '@/features/shell/utils/changeAppLocale'
import type { UserProfile } from '@/shared/types/auth.types'
import {
  PROFILE_WIZARD_TOTAL_STEPS,
  profileFormToUpdateInput,
  profileSchema,
  profileWizardAddressSchema,
  profileWizardContactSchema,
  profileWizardNameSchema,
  type ProfileFormValues,
  type ProfileWizardStep,
  userToProfileFormValues,
} from '../schemas/profileSchemas'
import { ProfileMediaSelectorModal } from './ProfileMediaSelectorModal'
import { ProfileWizardProgress } from './profile-wizard/ProfileWizardProgress'
import { ProfileWizardStepAccount } from './profile-wizard/ProfileWizardStepAccount'
import { ProfileWizardStepAddress } from './profile-wizard/ProfileWizardStepAddress'
import { ProfileWizardStepContact } from './profile-wizard/ProfileWizardStepContact'
import { ProfileWizardStepName } from './profile-wizard/ProfileWizardStepName'
import { ProfileWizardStepSummary } from './profile-wizard/ProfileWizardStepSummary'

const PROFILE_WIZARD_DIALOG_SIZE = {
  sizeWidth: 'large' as const,
  sizeHeight: 'xlarge' as const,
}

const PROFILE_EDIT_EMBED_PATH = '/embed/dialogs/profile/edit'

function readSavedProfileUser(payload: unknown): UserProfile | null {
  if (!payload || typeof payload !== 'object' || !('user' in payload)) {
    return null
  }
  const user = (payload as { user: UserProfile }).user
  if (!user || typeof user !== 'object' || typeof user.id !== 'string') {
    return null
  }
  return user
}

export interface ProfileFormDialogProps {
  open: boolean
  initialStep?: ProfileWizardStep
  onOpenChange: (open: boolean) => void
  onSaved: (user?: UserProfile) => void
  chrome?: 'dialog' | 'embed-page'
}

export function ProfileFormDialog({
  open,
  initialStep = 1,
  onOpenChange,
  onSaved,
  chrome = 'dialog',
}: ProfileFormDialogProps) {
  const { t } = useTranslation('profile')
  const { t: tc } = useTranslation('common')
  const dispatch = useAppDispatch()
  const [searchParams] = useSearchParams()
  const parentOrigin = resolvePlatformEmbedParentOrigin(searchParams, isAllowedParentOrigin)
  const user = useAppSelector((s) => s.auth.user)
  const accessToken = useAppSelector((s) => s.auth.accessToken)
  const isProfileSaving = useAppSelector((s) => s.auth.isProfileSaving)
  const profileError = useAppSelector((s) => s.auth.profileError)
  const profileSaveSuccess = useAppSelector((s) => s.auth.profileSaveSuccess)

  const embedStep =
    chrome === 'embed-page'
      ? (() => {
          const n = Number(searchParams.get('step'))
          if (n === 2 || n === 3 || n === 4 || n === 5) return n as ProfileWizardStep
          return 1 as ProfileWizardStep
        })()
      : initialStep
  const stepQuery = embedStep > 1 ? `?step=${embedStep}` : ''
  const path = `${PROFILE_EDIT_EMBED_PATH}${stepQuery}`
  const dialogRequestId =
    chrome === 'embed-page'
      ? (searchParams.get(PLATFORM_EMBED_QUERY.DIALOG_REQUEST_ID)?.trim() ?? null)
      : null

  const STEP_TITLES = [
    t('wizard.steps.account'),
    t('wizard.steps.address'),
    t('wizard.steps.contact'),
    t('wizard.steps.name'),
    t('wizard.steps.summary'),
  ] as const

  const STEP_DESCRIPTIONS = [
    t('wizard.descriptions.account'),
    t('wizard.descriptions.address'),
    t('wizard.descriptions.contact'),
    t('wizard.descriptions.name'),
    t('wizard.descriptions.summary'),
  ] as const

  const title = t('editProfile')
  const finalSubmitLabel = t('saveChanges')

  const [step, setStep] = useState<ProfileWizardStep>(embedStep)
  const [values, setValues] = useState<ProfileFormValues | null>(null)
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof ProfileFormValues, string>>>(
    {},
  )
  const [phoneCountry, setPhoneCountry] = useState(() => getBrowserDefaultCountryIso2())
  const [phoneNational, setPhoneNational] = useState('')
  const [pendingAvatarUrl, setPendingAvatarUrl] = useState<string | null>(null)
  const [selectorOpen, setSelectorOpen] = useState(false)
  const [selectorOpenKey, setSelectorOpenKey] = useState(0)
  const [blockOuterDismiss, setBlockOuterDismiss] = useState(false)
  const submittedRef = useRef(false)
  const seededUserIdRef = useRef<string | null>(null)
  const selectorOpenRef = useRef(false)
  const blockOuterDismissRef = useRef(false)
  const blockTimerRef = useRef<number | null>(null)

  const primaryLabelForStep = (current: ProfileWizardStep, saving: boolean) => {
    if (saving) return t('saving')
    if (current < PROFILE_WIZARD_TOTAL_STEPS) return tc('next')
    return finalSubmitLabel
  }

  const { isHosted } = useRequestPlatformPeerDialog({
    parentOrigin: chrome === 'dialog' ? parentOrigin : null,
    open: chrome === 'dialog' && open,
    path,
    title,
    description: STEP_DESCRIPTIONS[embedStep - 1],
    submitLabel: primaryLabelForStep(embedStep, false),
    secondaryLabel: embedStep > 1 ? tc('previous') : undefined,
    ...PROFILE_WIZARD_DIALOG_SIZE,
    onResult: (payload) => {
      const savedUser = readSavedProfileUser(payload)
      if (savedUser) {
        dispatch(authActions.profileUpdateSucceeded(savedUser))
      } else {
        dispatch(authActions.profileFetchRequested({ force: true }))
      }
      onSaved(savedUser ?? undefined)
      onOpenChange(false)
    },
    onCancel: () => onOpenChange(false),
  })

  useEffect(() => {
    selectorOpenRef.current = selectorOpen
  }, [selectorOpen])

  useEffect(() => {
    return () => {
      if (blockTimerRef.current !== null) {
        window.clearTimeout(blockTimerRef.current)
      }
    }
  }, [])

  useEffect(() => {
    if (!open && chrome === 'dialog') return
    const nextStep = chrome === 'embed-page' ? embedStep : initialStep
    setStep(nextStep)
    setFieldErrors({})
    seededUserIdRef.current = null
    setPendingAvatarUrl(null)
    setSelectorOpen(false)
    setBlockOuterDismiss(false)
  }, [chrome, embedStep, initialStep, open])

  useEffect(() => {
    if ((!open && chrome === 'dialog') || !user) return
    if (seededUserIdRef.current === user.id) return
    seededUserIdRef.current = user.id
    setValues(userToProfileFormValues(user))
    const parsed = parsePhoneE164(user.phoneNumber, {
      fallbackIso2: getBrowserDefaultCountryIso2(),
      preferIso2: user.country ?? undefined,
    })
    setPhoneCountry(parsed.iso2)
    setPhoneNational(parsed.nationalNumber)
  }, [chrome, open, user])

  useEffect(() => {
    if (!submittedRef.current || isProfileSaving) return
    submittedRef.current = false
    if (!profileError) {
      const nextLocale = values?.locale
      if (nextLocale) {
        void changeAppLocale(normalizeLocale(nextLocale))
      }
      onSaved(user ?? undefined)
      if (chrome === 'dialog') {
        onOpenChange(false)
      }
    }
  }, [chrome, isProfileSaving, onOpenChange, onSaved, profileError, user, values?.locale])

  useEffect(() => {
    if (profileSaveSuccess) {
      const timer = window.setTimeout(() => {
        dispatch(authActions.clearProfileSaveSuccess())
      }, 3000)
      return () => window.clearTimeout(timer)
    }
  }, [profileSaveSuccess, dispatch])

  const closeMediaSelector = useCallback(() => {
    setSelectorOpen(false)
    selectorOpenRef.current = false
    blockOuterDismissRef.current = true
    setBlockOuterDismiss(true)
    if (blockTimerRef.current !== null) {
      window.clearTimeout(blockTimerRef.current)
    }
    blockTimerRef.current = window.setTimeout(() => {
      blockOuterDismissRef.current = false
      setBlockOuterDismiss(false)
      blockTimerRef.current = null
    }, 150)
  }, [])

  const openMediaSelector = useCallback(() => {
    if (!accessToken) return
    setSelectorOpenKey((key) => key + 1)
    selectorOpenRef.current = true
    setSelectorOpen(true)
  }, [accessToken])

  function patchValues(patch: Partial<ProfileFormValues>) {
    setValues((prev) => (prev ? { ...prev, ...patch } : prev))
  }

  function contactPhoneFromState(): string | null {
    return phoneNational.trim() ? formatPhoneE164(phoneCountry, phoneNational) : null
  }

  function validateStep(current: ProfileWizardStep): boolean {
    if (!values) return false

    if (current === 1) {
      setFieldErrors({})
      return true
    }

    if (current === 2) {
      const result = profileWizardAddressSchema.safeParse({
        addressLine1: values.addressLine1,
        addressLine2: values.addressLine2,
        city: values.city,
        stateRegion: values.stateRegion,
        postalCode: values.postalCode,
        country: values.country,
      })
      if (!result.success) {
        setFieldErrors(mapZodIssuesToFieldErrors(result.error.issues))
        return false
      }
      setFieldErrors({})
      return true
    }

    if (current === 3) {
      const result = profileWizardContactSchema.safeParse({
        phoneNumber: contactPhoneFromState(),
        locale: values.locale,
      })
      if (!result.success) {
        setFieldErrors(mapZodIssuesToFieldErrors(result.error.issues))
        return false
      }
      setFieldErrors({})
      return true
    }

    if (current === 4) {
      const result = profileWizardNameSchema.safeParse({
        firstName: values.firstName,
        lastName: values.lastName,
        displayName: values.displayName,
      })
      if (!result.success) {
        setFieldErrors(mapZodIssuesToFieldErrors(result.error.issues))
        return false
      }
      setFieldErrors({})
      return true
    }

    return true
  }

  function handleNext() {
    if (!validateStep(step)) return
    setStep((prev) => Math.min(prev + 1, PROFILE_WIZARD_TOTAL_STEPS) as ProfileWizardStep)
  }

  function handlePrevious() {
    setFieldErrors({})
    setStep((prev) => Math.max(prev - 1, 1) as ProfileWizardStep)
  }

  function handleSubmit() {
    if (!values || !accessToken) return

    for (const s of [2, 3, 4] as const) {
      if (!validateStep(s)) {
        setStep(s)
        return
      }
    }

    const phoneNumber = contactPhoneFromState()
    const parsed = profileSchema.safeParse({ ...values, phoneNumber })
    if (!parsed.success) {
      setFieldErrors(mapZodIssuesToFieldErrors(parsed.error.issues))
      return
    }
    setFieldErrors({})
    submittedRef.current = true
    dispatch(
      authActions.profileUpdateRequested({
        body: {
          ...profileFormToUpdateInput(parsed.data),
          ...(pendingAvatarUrl !== null ? { avatarUrl: pendingAvatarUrl } : {}),
        },
      }),
    )
  }

  function handlePrimaryAction() {
    if (step < PROFILE_WIZARD_TOTAL_STEPS) {
      handleNext()
      return
    }
    handleSubmit()
  }

  usePlatformPeerDialogSubmit({
    parentOrigin: chrome === 'embed-page' ? parentOrigin : null,
    requestId: dialogRequestId,
    onSubmit: () => {
      if (selectorOpenRef.current) return
      handlePrimaryAction()
    },
    onSecondary: () => {
      if (selectorOpenRef.current || isProfileSaving) return
      handlePrevious()
    },
  })

  useEffect(() => {
    if (chrome !== 'embed-page' || !parentOrigin || !dialogRequestId) return
    sendPlatformPeerDialogBusy(
      parentOrigin,
      dialogRequestId,
      isProfileSaving || selectorOpen,
      primaryLabelForStep(step, isProfileSaving),
      {
        description: STEP_DESCRIPTIONS[step - 1],
        secondaryLabel: step > 1 ? tc('previous') : null,
      },
    )
  }, [chrome, dialogRequestId, isProfileSaving, parentOrigin, selectorOpen, step])

  function handleFormOpenChange(next: boolean) {
    if (next) return
    if (selectorOpenRef.current || selectorOpen) {
      closeMediaSelector()
      return
    }
    if (blockOuterDismissRef.current || blockOuterDismiss) {
      return
    }
    onOpenChange(false)
  }

  function handleMediaSelect(items: MediaItemDto[]) {
    const item = items[0]
    if (item) {
      setPendingAvatarUrl(item.url)
      closeMediaSelector()
    }
  }

  if (!user || !values) {
    if (chrome === 'embed-page') {
      return (
        <div className="flex min-h-[200px] items-center justify-center p-6 text-sm text-muted-foreground">
          {t('loading')}
        </div>
      )
    }
    return null
  }

  const stepIndex = step - 1
  const displayAvatarUrl = pendingAvatarUrl ?? user.avatarUrl
  const phoneDisplay = contactPhoneFromState() ?? ''

  const footer = (
    <div className="flex flex-wrap items-center justify-end gap-2">
      <Button
        type="button"
        variant="outline"
        className="h-10 px-4 border-[hsl(var(--glass-border))] text-foreground hover:bg-accent"
        onClick={() => handleFormOpenChange(false)}
        disabled={isProfileSaving}
      >
        {tc('cancel')}
      </Button>
      {step > 1 ? (
        <Button
          type="button"
          variant="outline"
          className="h-10 px-4 border-[hsl(var(--glass-border))] text-foreground hover:bg-accent"
          onClick={handlePrevious}
          disabled={isProfileSaving}
        >
          <ChevronLeft className="mr-2 h-4 w-4" />
          {tc('previous')}
        </Button>
      ) : null}
      {step < PROFILE_WIZARD_TOTAL_STEPS ? (
        <Button
          type="button"
          className="h-10 px-4"
          onClick={handleNext}
          disabled={isProfileSaving || selectorOpen}
        >
          {tc('next')}
          <ChevronRight className="ml-2 h-4 w-4" />
        </Button>
      ) : (
        <Button
          type="button"
          className="h-10"
          onClick={handleSubmit}
          disabled={isProfileSaving || selectorOpen}
        >
          <Save className="mr-2 h-4 w-4" />
          {isProfileSaving ? t('saving') : finalSubmitLabel}
        </Button>
      )}
    </div>
  )

  const body = (
    <div className="space-y-6">
      <div className="space-y-2 text-center">
        <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
          {t('stepOf', {
            current: step,
            total: PROFILE_WIZARD_TOTAL_STEPS,
            title: STEP_TITLES[stepIndex],
          })}
        </p>
        <ProfileWizardProgress currentStep={step} totalSteps={PROFILE_WIZARD_TOTAL_STEPS} />
      </div>

      {profileError ? (
        <Alert variant="destructive">
          <AlertDescription>{profileError}</AlertDescription>
        </Alert>
      ) : null}

      {step === 1 ? (
        <ProfileWizardStepAccount
          displayName={values.displayName || user.displayName}
          email={user.email ?? ''}
          avatarUrl={displayAvatarUrl}
          isGoogleUser={user.isGoogleUser}
          isSubmitting={isProfileSaving}
          onEditImage={openMediaSelector}
        />
      ) : null}

      {step === 2 ? (
        <ProfileWizardStepAddress
          values={values}
          fieldErrors={fieldErrors}
          isSubmitting={isProfileSaving}
          onChange={patchValues}
        />
      ) : null}

      {step === 3 ? (
        <ProfileWizardStepContact
          values={values}
          phoneCountry={phoneCountry}
          phoneNational={phoneNational}
          fieldErrors={fieldErrors}
          isSubmitting={isProfileSaving}
          onChange={patchValues}
          onPhoneCountryChange={(country) => setPhoneCountry(country.iso2)}
          onPhoneNationalChange={setPhoneNational}
        />
      ) : null}

      {step === 4 ? (
        <ProfileWizardStepName
          values={values}
          fieldErrors={fieldErrors}
          isSubmitting={isProfileSaving}
          onChange={patchValues}
        />
      ) : null}

      {step === 5 ? (
        <ProfileWizardStepSummary
          values={values}
          phoneDisplay={phoneDisplay}
          email={user.email ?? ''}
          avatarUrl={pendingAvatarUrl}
        />
      ) : null}
    </div>
  )

  const mediaModal = (
    <ProfileMediaSelectorModal
      isOpen={selectorOpen}
      accessToken={accessToken}
      userId={user.id}
      openKey={selectorOpenKey}
      onSelect={handleMediaSelect}
      onClose={closeMediaSelector}
    />
  )

  if (chrome === 'embed-page') {
    return (
      <>
        <div className="flex w-full flex-col gap-4 p-4 sm:p-6">{body}</div>
        {mediaModal}
      </>
    )
  }

  if (isHosted) {
    return null
  }

  return (
    <>
      <CustomDialog
        open={open}
        onOpenChange={handleFormOpenChange}
        title={title}
        description={STEP_DESCRIPTIONS[stepIndex]}
        sizeWidth={PROFILE_WIZARD_DIALOG_SIZE.sizeWidth}
        sizeHeight={PROFILE_WIZARD_DIALOG_SIZE.sizeHeight}
        nestedDismissGuard={selectorOpen || blockOuterDismiss}
        footer={footer}
      >
        {body}
      </CustomDialog>
      {mediaModal}
    </>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import type { TFunction } from 'i18next'
import {
  PLATFORM_EMBED_QUERY,
  resolvePlatformEmbedParentOrigin,
  sendPlatformPeerDialogBusy,
  sendPlatformPeerDialogComplete,
  usePlatformPeerDialogSubmit,
  useRequestPlatformPeerDialog,
} from '@webonone/platform-embed'
import {
  Alert,
  AlertDescription,
  Button,
  CustomDialog,
  Form,
  FormField,
  OtpInput,
  Spinner,
  useToast,
} from '@webonone/ui-kit'
import { useAppDispatch } from '@/app/store/hooks'
import { authActions } from '@/features/auth/store'
import { isAllowedParentOrigin } from '@/features/shell/utils/platformConfig'
import { authApi, type AuthApiError } from '@/shared/services/authApi'
import type { UserProfile } from '@/shared/types/auth.types'

export type VerifyContactChannel = 'email' | 'phone'

const EMAIL_OTP_COUNTDOWN_SECONDS = 120
const PHONE_OTP_COUNTDOWN_SECONDS = 60

const DIALOG_SIZE = {
  sizeWidth: 'small' as const,
  sizeHeight: 'auto' as const,
}

function buildChannelConfig(t: TFunction<'profile'>) {
  return {
    email: {
      title: t('verify.email.title'),
      description: t('verify.email.description'),
      submitLabel: t('verify.email.submit'),
      otpLength: 6,
      countdownSeconds: EMAIL_OTP_COUNTDOWN_SECONDS,
      embedPath: '/embed/dialogs/profile/verify-email',
      formId: 'verify-email-otp-form',
      request: () => authApi.requestProfileEmailOtp(),
      verify: (otp: string) => authApi.verifyProfileEmailOtp({ otp }),
    },
    phone: {
      title: t('verify.phone.title'),
      description: t('verify.phone.description'),
      submitLabel: t('verify.phone.submit'),
      otpLength: 6,
      countdownSeconds: PHONE_OTP_COUNTDOWN_SECONDS,
      embedPath: '/embed/dialogs/profile/verify-phone',
      formId: 'verify-phone-otp-form',
      request: () => authApi.requestProfilePhoneOtp(),
      verify: (otp: string) => authApi.verifyProfilePhoneOtp({ otp }),
    },
  } as const
}

export type VerifyContactOtpDialogProps = {
  open: boolean
  channel: VerifyContactChannel
  contactHint: string
  onOpenChange: (open: boolean) => void
  onVerified: (user: UserProfile) => void
  chrome?: 'dialog' | 'embed-page'
}

export function VerifyContactOtpDialog({
  open,
  channel,
  contactHint,
  onOpenChange,
  onVerified,
  chrome = 'dialog',
}: VerifyContactOtpDialogProps) {
  const { t } = useTranslation('profile')
  const { t: tc } = useTranslation('common')
  const dispatch = useAppDispatch()
  const { toast } = useToast()
  const [searchParams] = useSearchParams()
  const parentOrigin = resolvePlatformEmbedParentOrigin(searchParams, isAllowedParentOrigin)
  const config = buildChannelConfig(t)[channel]
  const dialogRequestId =
    chrome === 'embed-page'
      ? (searchParams.get(PLATFORM_EMBED_QUERY.DIALOG_REQUEST_ID)?.trim() ?? null)
      : null

  const [otp, setOtp] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [attemptsRemaining, setAttemptsRemaining] = useState<number | null>(null)
  const [locked, setLocked] = useState(false)
  const [loading, setLoading] = useState(false)
  const [sending, setSending] = useState(false)
  const [secondsLeft, setSecondsLeft] = useState<number>(config.countdownSeconds)
  const sessionKeyRef = useRef<string | null>(null)

  const { isHosted } = useRequestPlatformPeerDialog({
    parentOrigin: chrome === 'dialog' ? parentOrigin : null,
    open: chrome === 'dialog' && open,
    path: config.embedPath,
    title: config.title,
    description: config.description,
    submitLabel: config.submitLabel,
    cancelLabel: tc('cancel'),
    ...DIALOG_SIZE,
    onResult: (payload) => {
      if (payload && typeof payload === 'object' && 'user' in payload) {
        const user = (payload as { user: UserProfile }).user
        dispatch(authActions.profileUpdateSucceeded(user))
        onVerified(user)
      } else {
        dispatch(authActions.profileFetchRequested({ force: true }))
      }
      onOpenChange(false)
    },
    onCancel: () => onOpenChange(false),
  })

  const sendOtp = useCallback(async () => {
    setSending(true)
    setError(null)
    try {
      await config.request()
      setSecondsLeft(config.countdownSeconds)
      setLocked(false)
      setAttemptsRemaining(null)
      setOtp('')
      toast({ title: t('verify.codeSentToast') })
    } catch (err) {
      const apiErr = err as AuthApiError
      setError(apiErr.message ?? t('errors.sendCodeFailed'))
      toast({
        title: t('verify.couldNotSendToast'),
        description: apiErr.message,
        variant: 'destructive',
      })
    } finally {
      setSending(false)
    }
  }, [config, t, toast])

  useEffect(() => {
    if (!open || isHosted) {
      sessionKeyRef.current = null
      return
    }

    const sessionKey = `${channel}:${chrome}`
    if (sessionKeyRef.current === sessionKey) {
      return
    }
    sessionKeyRef.current = sessionKey
    setOtp('')
    setError(null)
    setAttemptsRemaining(null)
    setLocked(false)
    setLoading(false)
    setSecondsLeft(config.countdownSeconds)
    void sendOtp()
  }, [open, isHosted, channel, chrome, sendOtp])

  useEffect(() => {
    if (!open || isHosted || secondsLeft <= 0) return
    const timer = window.setInterval(() => {
      setSecondsLeft((s) => Math.max(0, s - 1))
    }, 1000)
    return () => window.clearInterval(timer)
  }, [open, isHosted, secondsLeft])

  useEffect(() => {
    if (chrome !== 'embed-page' || !parentOrigin || !dialogRequestId) return
    sendPlatformPeerDialogBusy(parentOrigin, dialogRequestId, loading || sending, config.submitLabel, {
      description: config.description,
      secondaryLabel: null,
    })
  }, [
    chrome,
    parentOrigin,
    dialogRequestId,
    loading,
    sending,
    config.description,
    config.submitLabel,
  ])

  const expired = secondsLeft <= 0
  const disabled = loading || locked || expired || sending || otp.length !== config.otpLength

  const handleVerify = useCallback(async () => {
    if (loading || locked || sending || otp.length !== config.otpLength) return

    setLoading(true)
    setError(null)
    try {
      const result = await config.verify(otp)
      dispatch(authActions.profileUpdateSucceeded(result.user))
      toast({ title: channel === 'email' ? t('verify.emailVerifiedToast') : t('verify.phoneVerifiedToast') })
      if (chrome === 'embed-page' && parentOrigin && dialogRequestId) {
        sendPlatformPeerDialogComplete(parentOrigin, dialogRequestId, { user: result.user })
      } else {
        onVerified(result.user)
        onOpenChange(false)
      }
    } catch (err) {
      const apiErr = err as AuthApiError
      if (apiErr.code === 'OTP_MAX_ATTEMPTS') {
        setLocked(true)
        setAttemptsRemaining(0)
        setError(t('errors.tooManyAttempts'))
      } else if (typeof apiErr.attemptsRemaining === 'number') {
        setAttemptsRemaining(apiErr.attemptsRemaining)
        setError(apiErr.message)
      } else if (apiErr.code === 'OTP_EXPIRED') {
        setSecondsLeft(0)
        setError(t('errors.codeExpiredRequestNew'))
      } else {
        setError(apiErr.message ?? t('errors.verificationFailed'))
      }
    } finally {
      setLoading(false)
    }
  }, [
    loading,
    locked,
    sending,
    otp,
    config,
    dispatch,
    t,
    toast,
    channel,
    chrome,
    parentOrigin,
    dialogRequestId,
    onVerified,
    onOpenChange,
  ])

  usePlatformPeerDialogSubmit({
    parentOrigin: chrome === 'embed-page' ? parentOrigin : null,
    requestId: dialogRequestId,
    onSubmit: () => {
      void handleVerify()
    },
  })

  if (isHosted) {
    return null
  }

  const body = (
    <Form
      id={config.formId}
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault()
        void handleVerify()
      }}
    >
      <p className="text-sm text-muted-foreground">
        {t('verify.codeSentTo', { length: config.otpLength, contact: contactHint })}
      </p>
      {error ? (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}
      {!locked && !expired && attemptsRemaining !== null ? (
        <p className="text-sm text-muted-foreground">
          {t('verify.attemptsRemaining', { count: attemptsRemaining })}
        </p>
      ) : null}
      {!locked && !expired ? (
        <p className="text-sm text-muted-foreground">{t('verify.codeExpiresIn', { seconds: secondsLeft })}</p>
      ) : null}
      {(expired || locked) && !sending ? (
        <Alert>
          <AlertDescription>
            {locked ? `${t('verify.tooManyAttemptsShort')} ` : `${t('verify.codeExpired')} `}
            <button type="button" className="underline" onClick={() => void sendOtp()}>
              {t('verify.requestNewCode')}
            </button>
          </AlertDescription>
        </Alert>
      ) : null}
      <FormField
        label={t('verify.otpLabel', { length: config.otpLength })}
        htmlFor={`verify-${channel}-otp`}
        required
        className="text-center"
      >
        <OtpInput
          id={`verify-${channel}-otp`}
          length={config.otpLength}
          value={otp}
          disabled={loading || locked || sending}
          autoFocus
          className="justify-center"
          onChange={setOtp}
        />
      </FormField>
    </Form>
  )

  if (chrome === 'embed-page') {
    return <div className="p-1">{body}</div>
  }

  return (
    <CustomDialog
      open={open}
      onOpenChange={onOpenChange}
      title={config.title}
      description={config.description}
      {...DIALOG_SIZE}
      footer={
        <>
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
            {tc('cancel')}
          </Button>
          <Button type="submit" form={config.formId} disabled={disabled}>
            {loading || sending ? <Spinner size="sm" /> : config.submitLabel}
          </Button>
        </>
      }
    >
      {body}
    </CustomDialog>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Save } from 'lucide-react'
import {
  isPlatformPeerDialogNestedCancelMessage,
  isPlatformPeerDialogNestedResultMessage,
  PLATFORM_EMBED_QUERY,
  resolvePlatformEmbedParentOrigin,
  sendPlatformPeerDialogBusy,
  sendPlatformPeerDialogComplete,
  sendPlatformPeerDialogDismiss,
  sendPlatformPeerDialogNestedRequest,
  usePlatformPeerDialogSubmit,
  useRequestPlatformPeerDialog,
} from '@webonone/platform-embed'
import {
  Button,
  CustomDialog,
  USER_SELECTION_DIALOG_SIZE,
  UserSelectionDialog,
  type LoadUsersFn,
  type UserOption,
} from '@webonone/ui-kit'
import { useAppSelector } from '@/app/store/hooks'
import { isAllowedParentOrigin } from '@/features/shell/utils/platformConfig'
import {
  CreateCompanyUserForm,
  CREATE_COMPANY_USER_FORM_ID,
} from '@/features/users/components/CreateCompanyUserForm'
import type { CreateCompanyUserPayload } from '@/features/users/schemas/createCompanyUserSchemas'
import { createCompanyCustomer, listUsers } from '@/features/users/services/usersApi'
import { getSessionCompanyId } from '@/features/users/utils/currentRole'

const ADD_USER_DIALOG_PATH = '/embed/dialogs/users/add'
const CREATE_USER_DIALOG_PATH = '/embed/dialogs/users/create'

const CREATE_DIALOG_SIZE = {
  sizeWidth: 'small' as const,
  sizeHeight: 'auto' as const,
}

function createNestedRequestId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `peer-nested-${Date.now()}-${Math.random().toString(36).slice(2)}`
}

function isUserOption(value: unknown): value is UserOption {
  if (!value || typeof value !== 'object') {
    return false
  }
  const user = value as Record<string, unknown>
  return typeof user.id === 'string' && typeof user.displayName === 'string'
}

function toUserOption(customer: {
  id: string
  displayName: string
  email: string | null
  avatarUrl?: string | null
}): UserOption {
  return {
    id: customer.id,
    displayName: customer.displayName,
    email: customer.email,
    avatarUrl: customer.avatarUrl ?? null,
  }
}

export type AddCompanyUserDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (user: UserOption) => void
  onCreated: (user: UserOption) => void
  chrome?: 'dialog' | 'embed-page'
}

export function AddCompanyUserDialog({
  open,
  onOpenChange,
  onSelect,
  onCreated,
  chrome = 'dialog',
}: AddCompanyUserDialogProps) {
  const { t } = useTranslation('users')
  const [searchParams] = useSearchParams()
  const accessToken = useAppSelector((s) => s.auth.accessToken)
  const companyId = getSessionCompanyId(accessToken)
  const parentOrigin = resolvePlatformEmbedParentOrigin(searchParams, isAllowedParentOrigin)
  const dialogRequestId =
    chrome === 'embed-page'
      ? (searchParams.get(PLATFORM_EMBED_QUERY.DIALOG_REQUEST_ID)?.trim() ?? null)
      : null

  const [pendingSelection, setPendingSelection] = useState<UserOption | null>(null)
  const [createOpen, setCreateOpen] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)
  const [blockOuterDismiss, setBlockOuterDismiss] = useState(false)
  const nestedRequestIdRef = useRef<string | null>(null)
  const createOpenRef = useRef(false)
  const blockOuterDismissRef = useRef(false)
  const blockTimerRef = useRef<number | null>(null)

  const { isHosted } = useRequestPlatformPeerDialog({
    parentOrigin: chrome === 'dialog' ? parentOrigin : null,
    open: chrome === 'dialog' && open,
    path: ADD_USER_DIALOG_PATH,
    title: t('addDialog.title'),
    description: t('addDialog.description'),
    submitLabel: t('addDialog.submit'),
    ...USER_SELECTION_DIALOG_SIZE,
    onResult: (payload) => {
      if (payload && typeof payload === 'object' && isUserOption(payload)) {
        const record = payload as UserOption & {
          alreadyAdded?: boolean
        }
        if (record.alreadyAdded) {
          onCreated(record)
        } else {
          onSelect(record)
        }
      }
      onOpenChange(false)
    },
    onCancel: () => onOpenChange(false),
  })

  const loadUsersForPicker: LoadUsersFn = useCallback(
    async ({ search, page, pageSize }) => {
      const result = await listUsers({
        search,
        role: null,
        page,
        pageSize,
        excludeCompanyId: companyId,
      })
      return {
        users: result.items.map(
          (user): UserOption => ({
            id: user.id,
            displayName: user.displayName,
            email: user.email,
            role: user.role,
            avatarUrl: user.avatarUrl,
          }),
        ),
        hasMore: page * pageSize < result.total,
      }
    },
    [companyId],
  )

  useEffect(() => {
    createOpenRef.current = createOpen
  }, [createOpen])

  const closeCreateDialog = useCallback(() => {
    setCreateOpen(false)
    setCreateError(null)
    nestedRequestIdRef.current = null
    blockOuterDismissRef.current = true
    setBlockOuterDismiss(true)
    if (blockTimerRef.current !== null) {
      window.clearTimeout(blockTimerRef.current)
    }
    blockTimerRef.current = window.setTimeout(() => {
      blockOuterDismissRef.current = false
      setBlockOuterDismiss(false)
      blockTimerRef.current = null
    }, 150)
  }, [])

  const openCreateDialog = useCallback(() => {
    if (chrome === 'embed-page' && parentOrigin && dialogRequestId) {
      const nestedRequestId = createNestedRequestId()
      nestedRequestIdRef.current = nestedRequestId
      createOpenRef.current = true
      setCreateOpen(true)
      sendPlatformPeerDialogNestedRequest(parentOrigin, {
        parentRequestId: dialogRequestId,
        requestId: nestedRequestId,
        path: CREATE_USER_DIALOG_PATH,
        title: t('createDialog.title'),
        description: t('createDialog.description'),
        submitLabel: t('createDialog.submit'),
        ...CREATE_DIALOG_SIZE,
      })
      return
    }
    createOpenRef.current = true
    setCreateOpen(true)
    setCreateError(null)
  }, [chrome, dialogRequestId, parentOrigin, t])

  useEffect(() => {
    return () => {
      if (blockTimerRef.current !== null) {
        window.clearTimeout(blockTimerRef.current)
      }
    }
  }, [])

  useEffect(() => {
    if (!open) {
      setCreateOpen(false)
      createOpenRef.current = false
      nestedRequestIdRef.current = null
      setCreateError(null)
      setPendingSelection(null)
      setCreating(false)
      setBlockOuterDismiss(false)
      blockOuterDismissRef.current = false
    }
  }, [open])

  useEffect(() => {
    if (chrome !== 'embed-page' || !parentOrigin || !dialogRequestId) {
      return
    }

    function handleMessage(event: MessageEvent) {
      if (event.origin !== parentOrigin || event.source !== window.parent) {
        return
      }
      const nestedId = nestedRequestIdRef.current
      if (!nestedId) {
        return
      }

      if (
        isPlatformPeerDialogNestedResultMessage(event.data) &&
        event.data.parentRequestId === dialogRequestId &&
        event.data.requestId === nestedId
      ) {
        nestedRequestIdRef.current = null
        setCreateOpen(false)
        createOpenRef.current = false
        const payload = event.data.payload
        if (payload && typeof payload === 'object' && isUserOption(payload)) {
          sendPlatformPeerDialogComplete(parentOrigin!, dialogRequestId!, {
            ...payload,
            alreadyAdded: true,
          })
        }
        return
      }

      if (
        isPlatformPeerDialogNestedCancelMessage(event.data) &&
        event.data.parentRequestId === dialogRequestId &&
        event.data.requestId === nestedId
      ) {
        closeCreateDialog()
      }
    }

    window.addEventListener('message', handleMessage)
    return () => window.removeEventListener('message', handleMessage)
  }, [chrome, closeCreateDialog, dialogRequestId, parentOrigin])

  async function handleCreateSubmit(values: CreateCompanyUserPayload) {
    if (!companyId) {
      return
    }
    setCreating(true)
    setCreateError(null)
    try {
      const result = await createCompanyCustomer({
        companyId,
        firstName: values.firstName,
        lastName: values.lastName,
        email: values.email,
        phoneNumber: values.phoneNumber,
      })
      const user = toUserOption(result)
      closeCreateDialog()
      onCreated(user)
      onOpenChange(false)
    } catch (err) {
      setCreateError(err instanceof Error ? err.message : t('errors.createFailed'))
    } finally {
      setCreating(false)
    }
  }

  usePlatformPeerDialogSubmit({
    parentOrigin: chrome === 'embed-page' ? parentOrigin : null,
    requestId: dialogRequestId,
    onSubmit: () => {
      if (createOpenRef.current) {
        return
      }
      if (!pendingSelection || !parentOrigin || !dialogRequestId) {
        return
      }
      sendPlatformPeerDialogComplete(parentOrigin, dialogRequestId, pendingSelection)
    },
  })

  useEffect(() => {
    if (chrome !== 'embed-page' || !parentOrigin || !dialogRequestId) {
      return
    }
    if (createOpen) {
      sendPlatformPeerDialogBusy(parentOrigin, dialogRequestId, true, t('addDialog.submit'))
      return
    }
    sendPlatformPeerDialogBusy(
      parentOrigin,
      dialogRequestId,
      !pendingSelection,
      t('addDialog.submit'),
    )
  }, [chrome, createOpen, dialogRequestId, parentOrigin, pendingSelection])

  function handlePickerOpenChange(next: boolean) {
    if (!next && (createOpenRef.current || blockOuterDismissRef.current || blockOuterDismiss)) {
      if (createOpenRef.current || createOpen) {
        closeCreateDialog()
      }
      return
    }
    if (chrome === 'embed-page' && parentOrigin && dialogRequestId && !next) {
      sendPlatformPeerDialogDismiss(parentOrigin, dialogRequestId)
      return
    }
    onOpenChange(next)
  }

  if (chrome === 'embed-page') {
    if (!parentOrigin || !dialogRequestId) {
      return null
    }
    return (
      <UserSelectionDialog
        chrome="body"
        open
        onOpenChange={handlePickerOpenChange}
        onSelect={() => {
          /* Done is host footer via peer-dialog-submit */
        }}
        onPendingChange={setPendingSelection}
        onAddUser={openCreateDialog}
        loadUsers={loadUsersForPicker}
        emptyMessage={t('empty.addDialog')}
      />
    )
  }

  if (isHosted) {
    return null
  }

  return (
    <>
      <UserSelectionDialog
        open={open}
        onOpenChange={handlePickerOpenChange}
        onSelect={onSelect}
        loadUsers={loadUsersForPicker}
        title={t('addDialog.title')}
        description={t('addDialog.description')}
        emptyMessage={t('empty.addDialog')}
        onAddUser={openCreateDialog}
        nestedDismissGuard={createOpen || blockOuterDismiss}
      />
      <CustomDialog
        open={createOpen}
        onOpenChange={(next) => {
          if (!next) {
            closeCreateDialog()
          }
        }}
        title={t('createDialog.title')}
        description={t('createDialog.description')}
        stackLevel={1}
        sizeWidth={CREATE_DIALOG_SIZE.sizeWidth}
        sizeHeight={CREATE_DIALOG_SIZE.sizeHeight}
        footer={
          <>
            <Button
              type="button"
              variant="outline"
              className="h-10 px-4"
              onClick={(event) => {
                event.stopPropagation()
                closeCreateDialog()
              }}
              disabled={creating}
            >
              {t('common:cancel')}
            </Button>
            <Button
              type="submit"
              form={CREATE_COMPANY_USER_FORM_ID}
              className="h-10 px-4"
              disabled={creating}
            >
              <Save className="mr-2 h-4 w-4" aria-hidden />
              {creating ? t('createDialog.creating') : t('createDialog.submit')}
            </Button>
          </>
        }
      >
        <CreateCompanyUserForm
          error={createError}
          disabled={creating}
          onSubmit={(values) => {
            void handleCreateSubmit(values)
          }}
        />
      </CustomDialog>
    </>
  )
}

import { useTranslation } from 'react-i18next'
import { useState } from 'react'
import type { FormEvent } from 'react'
import {
  Alert,
  AlertDescription,
  FormField,
  Input,
  PhoneInput,
  formatPhoneE164,
  getBrowserDefaultCountryIso2,
  mapZodIssuesToFieldErrors,
} from '@webonone/ui-kit'
import {
  createCompanyUserSchema,
  type CreateCompanyUserPayload,
} from '@/features/users/schemas/createCompanyUserSchemas'

export const CREATE_COMPANY_USER_FORM_ID = 'create-company-user-form'

export type CreateCompanyUserFormProps = {
  formId?: string
  error?: string | null
  disabled?: boolean
  onSubmit: (values: CreateCompanyUserPayload) => void
}

export function CreateCompanyUserForm({
  formId = CREATE_COMPANY_USER_FORM_ID,
  error,
  disabled,
  onSubmit,
}: CreateCompanyUserFormProps) {
  const { t } = useTranslation('users')
  const [firstName, setFirstName] = useState('')
  const [lastName, setLastName] = useState('')
  const [email, setEmail] = useState('')
  const [phoneCountry, setPhoneCountry] = useState(() => getBrowserDefaultCountryIso2())
  const [phoneNational, setPhoneNational] = useState('')
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})

  function handleSubmit(event?: FormEvent) {
    event?.preventDefault()
    const phoneNumber = phoneNational.trim()
      ? formatPhoneE164(phoneCountry, phoneNational)
      : ''
    const parsed = createCompanyUserSchema.safeParse({
      firstName,
      lastName,
      email,
      phoneNumber,
    })
    if (!parsed.success) {
      setFieldErrors(mapZodIssuesToFieldErrors(parsed.error.issues) as Record<string, string>)
      return
    }
    setFieldErrors({})
    onSubmit(parsed.data)
  }

  return (
    <form id={formId} className="space-y-4" onSubmit={handleSubmit}>
      {error ? (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      <FormField
        label={t('form.firstName')}
        htmlFor="create-user-first-name"
        required
        error={fieldErrors.firstName ? t(fieldErrors.firstName) : undefined}
      >
        <Input
          id="create-user-first-name"
          value={firstName}
          disabled={disabled}
          onChange={(e) => setFirstName(e.target.value)}
          autoComplete="given-name"
        />
      </FormField>

      <FormField
        label={t('form.lastName')}
        htmlFor="create-user-last-name"
        required
        error={fieldErrors.lastName ? t(fieldErrors.lastName) : undefined}
      >
        <Input
          id="create-user-last-name"
          value={lastName}
          disabled={disabled}
          onChange={(e) => setLastName(e.target.value)}
          autoComplete="family-name"
        />
      </FormField>

      <FormField label={t('form.email')} htmlFor="create-user-email" error={fieldErrors.email ? t(fieldErrors.email) : undefined}>
        <Input
          id="create-user-email"
          type="email"
          value={email}
          disabled={disabled}
          onChange={(e) => setEmail(e.target.value)}
          autoComplete="email"
          placeholder={t('form.emailPlaceholder')}
        />
      </FormField>

      <FormField
        label={t('form.phoneNumber')}
        htmlFor="create-user-phone"
        error={fieldErrors.phoneNumber ? t(fieldErrors.phoneNumber) : undefined}
      >
        <PhoneInput
          id="create-user-phone"
          withIcon
          country={phoneCountry}
          onCountryChange={(country) => setPhoneCountry(country.iso2)}
          value={phoneNational}
          disabled={disabled}
          onChange={(e) => setPhoneNational(e.target.value)}
          aria-invalid={Boolean(fieldErrors.phoneNumber)}
        />
      </FormField>
    </form>
  )
}

export function submitCreateCompanyUserForm(formId = CREATE_COMPANY_USER_FORM_ID) {
  const form = document.getElementById(formId)
  if (form instanceof HTMLFormElement) {
    form.requestSubmit()
  }
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import {
  Alert,
  AlertDescription,
  ItemList,
  ItemListContent,
  ItemListEmpty,
  ItemListItem,
  Spinner,
  cn,
} from '@webonone/ui-kit'
import {
  loadUserHistory,
  resolveSaleId,
  resolveSessionTokenId,
  type UserHistoryItem,
} from '@/features/users/services/userHistoryApi'
import { formatDisplayDateTime } from '@/shared/utils/formatDisplayDate'
import type { IdentityUserDetail } from '@/features/users/types'
import { useAppSelector } from '@/app/store/hooks'
import {
  getSessionCompanyId,
  isSessionSuperAdmin,
} from '@/features/users/utils/currentRole'

function historyTitle(item: UserHistoryItem): string {
  if (item.kind === 'form_submission') return item.formName
  return item.title
}

function historySubtitle(
  item: UserHistoryItem,
  t: (k: string, o?: Record<string, string>) => string,
  showCompany: boolean,
): string {
  const companyName =
    showCompany && item.kind === 'company_activity' && typeof item.meta?.companyName === 'string'
      ? item.meta.companyName
      : null
  const companyPart = companyName ? t('history.companyPrefix', { name: companyName }) : null

  if (item.kind === 'form_submission') {
    return [
      companyPart,
      item.serviceName ? t('history.servicePrefix', { name: item.serviceName }) : null,
      t('history.filledBy', { name: item.filledByDisplayName }),
    ]
      .filter(Boolean)
      .join(' ┬╖ ')
  }
  return [companyPart, item.subtitle, item.status ? t('history.statusPrefix', { status: item.status }) : null]
    .filter(Boolean)
    .join(' ┬╖ ')
}

function historyBadge(item: UserHistoryItem, t: (k: string) => string): string {
  if (item.kind === 'form_submission') return t('history.badgeForm')
  if (item.kind === 'company_activity' && item.type === 'sale') return t('history.badgeSale')
  return t('history.badgeSession')
}

type UserHistoryPanelProps = {
  user: IdentityUserDetail
}

export function UserHistoryPanel({ user }: UserHistoryPanelProps) {
  const { t } = useTranslation('users')
  const navigate = useNavigate()
  const accessToken = useAppSelector((s) => s.auth.accessToken)
  const showCompany = isSessionSuperAdmin(accessToken) && !getSessionCompanyId(accessToken)
  const [items, setItems] = useState<UserHistoryItem[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    setError(null)
    loadUserHistory(user.id)
      .then((next) => {
        if (!cancelled) setItems(next)
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : t('errors.loadHistoryFailed'))
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [user.id])

  function openHistoryItem(item: UserHistoryItem) {
    if (item.kind === 'form_submission') {
      navigate(`/users/${user.id}/history/submissions/${item.id}`)
      return
    }
    if (item.type === 'session_token') {
      const tokenId = resolveSessionTokenId(item)
      if (tokenId) navigate(`/users/${user.id}/history/tokens/${tokenId}`)
      return
    }
    if (item.type === 'sale') {
      const saleId = resolveSaleId(item)
      if (saleId) navigate(`/users/${user.id}/history/sales/${saleId}`)
    }
  }

  if (loading) {
    return (
      <div className="flex justify-center py-10">
        <Spinner />
      </div>
    )
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    )
  }

  return (
    <div className="flex flex-col gap-4">
      {items.length === 0 ? (
        <ItemListEmpty>{t('empty.history')}</ItemListEmpty>
      ) : (
        <ItemList>
          {items.map((item) => {
            const when = item.kind === 'form_submission' ? item.createdAt : item.occurredAt
            const clickable =
              item.kind === 'form_submission' ||
              (item.kind === 'company_activity' &&
                (item.type === 'session_token' || item.type === 'sale'))
            return (
              <ItemListItem key={item.id}>
                <ItemListContent>
                  {clickable ? (
                    <button
                      type="button"
                      className="flex w-full flex-wrap items-start justify-between gap-2 rounded-md text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      onClick={() => openHistoryItem(item)}
                    >
                      <div className="min-w-0 flex-1 space-y-1">
                        <p className="text-sm font-medium">{historyTitle(item)}</p>
                        <p className="text-xs text-muted-foreground">{historySubtitle(item, t, showCompany)}</p>
                        <p className="text-xs text-muted-foreground">{formatDisplayDateTime(when)}</p>
                      </div>
                      <span
                        className={cn(
                          'rounded-md bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground',
                        )}
                      >
                        {historyBadge(item, t)}
                      </span>
                    </button>
                  ) : (
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div className="min-w-0 flex-1 space-y-1">
                        <p className="text-sm font-medium">{historyTitle(item)}</p>
                        <p className="text-xs text-muted-foreground">{historySubtitle(item, t, showCompany)}</p>
                        <p className="text-xs text-muted-foreground">{formatDisplayDateTime(when)}</p>
                      </div>
                      <span
                        className={cn(
                          'rounded-md bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground',
                        )}
                      >
                        {historyBadge(item, t)}
                      </span>
                    </div>
                  )}
                </ItemListContent>
              </ItemListItem>
            )
          })}
        </ItemList>
      )}
    </div>
  )
}

