export function HistoryTokenDetailPage() {
  const { t } = useTranslation('users')
  const { id: userId, tokenId } = useParams<{ id: string; tokenId: string }>()
  const navigate = useNavigate()
  const [detail, setDetail] = useState<SessionTokenHistoryDetail | null>(null)
  const [submissions, setSubmissions] = useState<FormSubmissionDetail[]>([])
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const reloadSubmissions = useCallback(() => {
    if (!tokenId) return
    listSubmissionsForSessionToken(tokenId)
      .then(setSubmissions)
      .catch(() => {
        /* keep existing submissions on soft refresh failure */
      })
  }, [tokenId])

  const { open: openFormDialog } = useOpenDesignFormDialog(reloadSubmissions)

  usePlatformLoading(loading && !detail ? t('loading.history') : null)

  useEffect(() => {
    if (!tokenId) return
    let cancelled = false
    setLoading(true)
    setError(null)
    Promise.all([getSessionTokenHistoryDetail(tokenId), listSubmissionsForSessionToken(tokenId)])
      .then(([nextDetail, nextSubs]) => {
        if (cancelled) return
        setDetail(nextDetail)
        setSubmissions(nextSubs)
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : t('errors.loadHistoryDetailFailed'))
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [tokenId])

  const backToUser = () => {
    if (userId) navigate(`/users/${userId}?tab=history`)
    else navigate('/users')
  }

  if (loading && !detail) return null

  if (error && !detail) {
    return (
      <FeaturePage
        title={t('history.sessionHistoryTitle')}
        description={t('history.sessionHistoryLoadError')}
        onBack={backToUser}
        backLabel={t('common:back')}
      >
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      </FeaturePage>
    )
  }

  if (!detail) return null

  const primarySubmission = submissions[0] ?? null
  const formTemplateId = primarySubmission?.formTemplateId ?? detail.formTemplateId

  function openFill() {
    if (!formTemplateId) return
    openFormDialog({
      formTemplateId,
      subjectUserId: detail!.userId,
      subjectDisplayName: detail!.userDisplayName,
      subjectEmail: detail!.userEmail,
      serviceId: detail!.serviceId,
      serviceName: detail!.serviceName,
      eventId: detail!.eventId,
      occurrenceDate: detail!.occurrenceDate,
      sessionTokenId: detail!.tokenId,
      mode: 'fill',
    })
  }

  function openView() {
    if (!primarySubmission) return
    openFormDialog({
      formTemplateId: primarySubmission.formTemplateId,
      subjectUserId: primarySubmission.subjectUserId,
      subjectDisplayName: primarySubmission.subjectDisplayName,
      subjectEmail: primarySubmission.subjectEmail,
      serviceId: primarySubmission.serviceId ?? detail!.serviceId,
      serviceName: primarySubmission.serviceName ?? detail!.serviceName,
      eventId: primarySubmission.eventId ?? detail!.eventId,
      occurrenceDate: primarySubmission.occurrenceDate ?? detail!.occurrenceDate,
      sessionTokenId: primarySubmission.sessionTokenId ?? detail!.tokenId,
      mode: 'view',
      submissionId: primarySubmission.id,
    })
  }

  return (
    <FeaturePage
      title={detail.serviceName}
      description={t('history.tokenDescription', { label: detail.tokenLabel, date: formatCalendarYmd(detail.occurrenceDate) })}
      onBack={backToUser}
      backLabel={t('common:back')}
    >
      <div className="grid grid-cols-1 items-start gap-6 lg:grid-cols-3">
        <div className="flex flex-col gap-6 lg:col-span-2">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">{t('history.sessionCardTitle')}</CardTitle>
              <CardDescription>{t('history.sessionCardDescription')}</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <DetailField label={t('history.service')} value={detail.serviceName} />
              <DetailField label={t('history.date')} value={formatCalendarYmd(detail.occurrenceDate)} />
              <DetailField label={t('history.time')} value={`${detail.startTime}ΓÇô${detail.endTime}`} />
              <DetailField label={t('history.token')} value={detail.tokenLabel} />
              {detail.workflowProgress ? (
                <div className="space-y-1">
                  <p className="text-xs font-medium text-muted-foreground">{t('history.progress')}</p>
                  <TokenWorkflowProgress progress={detail.workflowProgress} />
                </div>
              ) : null}
              <DetailField label={t('history.status')} value={detail.status} />
              <DetailField label={t('history.customer')} value={detail.userDisplayName} />
              {detail.spaceName ? <DetailField label={t('history.space')} value={detail.spaceName} /> : null}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-lg">{t('history.formCardTitle')}</CardTitle>
              <CardDescription>{t('history.formCardSessionDescription')}</CardDescription>
            </CardHeader>
            <CardContent>
              {!formTemplateId ? (
                <ItemListEmpty>{t('empty.noFormLinked')}</ItemListEmpty>
              ) : primarySubmission ? (
                <Button type="button" size="sm" variant="outline" onClick={openView}>
                  {t('history.viewForm')}
                </Button>
              ) : (
                <Button type="button" size="sm" onClick={openFill}>
                  {t('history.fillForm')}
                </Button>
              )}
            </CardContent>
          </Card>

          <Card variant="list">
            <CardHeader>
              <CardTitle className="text-lg">{t('history.salesCardTitle')}</CardTitle>
              <CardDescription>{t('history.salesCardDescription')}</CardDescription>
            </CardHeader>
            <CardContent>
              {detail.sales.length === 0 ? (
                <ItemListEmpty>{t('history.salesEmpty')}</ItemListEmpty>
              ) : (
                <ItemList className="py-0">
                  {detail.sales.map((sale) => (
                    <ItemListItem
                      key={sale.id}
                      role="button"
                      tabIndex={0}
                      className="cursor-pointer"
                      onClick={() => userId && navigate(`/users/${userId}/history/sales/${sale.id}`)}
                      onKeyDown={(event) => {
                        if (event.key === 'Enter' || event.key === ' ') {
                          event.preventDefault()
                          if (userId) navigate(`/users/${userId}/history/sales/${sale.id}`)
                        }
                      }}
                    >
                      <ItemListContent>
                        <p className="font-medium">{sale.billNumber}</p>
                        <p className="text-sm text-muted-foreground">
                          {sale.currency} {sale.total.toFixed(2)} ┬╖ {sale.paymentMethod}
                        </p>
                      </ItemListContent>
                    </ItemListItem>
                  ))}
                </ItemList>
              )}
            </CardContent>
          </Card>
        </div>

        <div className="flex flex-col gap-6 lg:col-span-1">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">{t('history.staffTitle')}</CardTitle>
              <CardDescription>{t('history.staffDescription')}</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <DetailField label={t('history.staffName')} value={detail.staffDisplayName} />
            </CardContent>
          </Card>
        </div>
      </div>
    </FeaturePage>
  )
}

import { useEffect, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import {
  getPlatformEmbedParentOrigin,
  PLATFORM_EMBED_QUERY,
  sendPlatformPeerDialogBusy,
  sendPlatformPeerDialogComplete,
  usePlatformPeerDialogSubmit,
} from '@webonone/platform-embed'
import { Alert, AlertDescription } from '@webonone/ui-kit'
import { useAppSelector } from '@/app/store/hooks'
import { isAllowedParentOrigin } from '@/features/shell/utils/platformConfig'
import { CreateCompanyUserForm } from '@/features/users/components/CreateCompanyUserForm'
import type { CreateCompanyUserPayload } from '@/features/users/schemas/createCompanyUserSchemas'
import { createCompanyCustomer } from '@/features/users/services/usersApi'
import { getSessionCompanyId } from '@/features/users/utils/currentRole'

/**
 * Body-only create form for core-hosted nested sibling dialog
 * (SelectTag create pattern ΓÇö host owns Cancel/Create footer).
 */
export function UserCreateEmbedPage() {
  const { t } = useTranslation('users')
  const [searchParams] = useSearchParams()
  const accessToken = useAppSelector((s) => s.auth.accessToken)
  const companyId = getSessionCompanyId(accessToken)
  const parentOrigin = getPlatformEmbedParentOrigin(searchParams, isAllowedParentOrigin)
  const requestId = searchParams.get(PLATFORM_EMBED_QUERY.DIALOG_REQUEST_ID)?.trim() ?? ''
  const [error, setError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)

  usePlatformPeerDialogSubmit({
    parentOrigin,
    requestId: requestId || null,
    onSubmit: () => {
      const form = document.getElementById('create-company-user-form')
      if (form instanceof HTMLFormElement) {
        form.requestSubmit()
      }
    },
  })

  useEffect(() => {
    if (!parentOrigin || !requestId) {
      return
    }
    sendPlatformPeerDialogBusy(
      parentOrigin,
      requestId,
      creating,
      creating ? t('createDialog.creating') : t('createDialog.submit'),
    )
  }, [creating, parentOrigin, requestId])

  async function handleSubmit(values: CreateCompanyUserPayload) {
    if (!companyId || !parentOrigin || !requestId) {
      return
    }
    setCreating(true)
    setError(null)
    try {
      const result = await createCompanyCustomer({
        companyId,
        firstName: values.firstName,
        lastName: values.lastName,
        email: values.email,
        phoneNumber: values.phoneNumber,
      })
      sendPlatformPeerDialogComplete(parentOrigin, requestId, {
        id: result.id,
        displayName: result.displayName,
        email: result.email,
        avatarUrl: result.avatarUrl ?? null,
        alreadyAdded: true,
      })
    } catch (err) {
      setError(err instanceof Error ? err.message : t('errors.createFailed'))
    } finally {
      setCreating(false)
    }
  }

  if (!parentOrigin || !requestId) {
    return (
      <div className="flex min-h-[200px] items-center justify-center p-6">
        <Alert variant="destructive" className="max-w-sm">
          <AlertDescription>
            {t('errors.peerDialogOnly')}
          </AlertDescription>
        </Alert>
      </div>
    )
  }

  return (
    <div className="flex w-full flex-col gap-4 p-4 sm:p-6">
      <CreateCompanyUserForm
        error={error}
        disabled={creating}
        onSubmit={(values) => {
          void handleSubmit(values)
        }}
      />
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Navigate, useParams, useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import {
  Alert,
  AlertDescription,
  FeaturePage,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
  tabsPageClassName,
  tabsPageContentClassName,
} from '@webonone/ui-kit'
import { useAppSelector } from '@/app/store/hooks'
import { usePlatformLoading } from '@/features/auth/context/PlatformLoadingContext'
import { hasPlatformEmbedHandoff } from '@/features/auth/utils/platformReturn'
import { ProfileView } from '@/features/profile/components/ProfileView'
import { UserHistoryPanel } from '@/features/users/components/UserHistoryPanel'
import { getUser } from '@/features/users/services/usersApi'
import type { IdentityUserDetail } from '@/features/users/types'
import {
  canAccessCompanyCustomers,
  getSessionCompanyId,
  isSessionSuperAdmin,
} from '@/features/users/utils/currentRole'
import { useNavigateIdentity } from '@/features/shell/utils/navigateIdentity'
import { useDetailTabParam } from '@/shared/hooks/useDetailTabParam'

const USER_DETAIL_TABS = ['overview', 'history'] as const
type UserDetailTab = (typeof USER_DETAIL_TABS)[number]

export function UserDetailsPage() {
  const { t } = useTranslation('users')
  const { id } = useParams<{ id: string }>()
  const { goToUsersList, syncShellUserTab } = useNavigateIdentity()
  const [searchParams] = useSearchParams()
  const accessToken = useAppSelector((s) => s.auth.accessToken)
  const isSuperAdmin = isSessionSuperAdmin(accessToken)
  const companyId = getSessionCompanyId(accessToken)
  const isEmbedHandoff = hasPlatformEmbedHandoff(searchParams)
  const companyCustomersMode = Boolean(companyId) && canAccessCompanyCustomers(accessToken)
  const canView = Boolean(accessToken) && (isSuperAdmin || companyCustomersMode)

  const [tab, setTab] = useDetailTabParam<UserDetailTab>(USER_DETAIL_TABS, 'overview')

  const [user, setUser] = useState<IdentityUserDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  usePlatformLoading(loading && !user ? t('loading.user') : null)

  useEffect(() => {
    if (!canView || !id) {
      return
    }

    let cancelled = false
    setLoading(true)
    setError(null)

    getUser(id)
      .then((detail) => {
        if (!cancelled) {
          setUser(detail)
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setUser(null)
          setError(err instanceof Error ? err.message : t('errors.loadUserFailed'))
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [canView, id])

  if (!accessToken) {
    if (isEmbedHandoff) {
      return null
    }
    return <Navigate to="/login" replace />
  }

  if (!isSuperAdmin && !companyCustomersMode) {
    return <Navigate to="/profile" replace />
  }

  if (!id) {
    return <Navigate to="/users" replace />
  }

  function handleBack() {
    goToUsersList()
  }

  function handleTabChange(next: UserDetailTab) {
    setTab(next)
    if (id) {
      syncShellUserTab(id, next)
    }
  }

  const tabs: { id: UserDetailTab; label: string }[] = [
    { id: 'overview', label: t('tabs.overview') },
    { id: 'history', label: t('tabs.history') },
  ]

  // Keep FeaturePage mounted while loading (no blank return) ΓÇö matches Data details.
  return (
    <FeaturePage
      title={user?.displayName ?? t('userFallbackTitle')}
      description={t('userDetailsDescription')}
      onBack={handleBack}
      backLabel={t('common:back')}
    >
      {error && !user ? (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      {user ? (
        <Tabs
          value={tab}
          onValueChange={(value) => handleTabChange(value as UserDetailTab)}
          className={tabsPageClassName}
        >
          <TabsList aria-label={t('sectionsAria')}>
            {tabs.map((item) => (
              <TabsTrigger key={item.id} value={item.id}>
                {item.label}
              </TabsTrigger>
            ))}
          </TabsList>

          <TabsContent value={tab} className={tabsPageContentClassName}>
            {tab === 'overview' ? (
              <ProfileView
                user={user}
                avatarUrl={user.avatarUrl}
                canEdit={false}
                role={user.role}
              />
            ) : (
              <UserHistoryPanel user={user} />
            )}
          </TabsContent>
        </Tabs>
      ) : null}
    </FeaturePage>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { ChangeEvent, KeyboardEvent } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Check } from 'lucide-react'
import {
  getPlatformEmbedParentOrigin,
  isIdentityUserPickerSetSelectionMessage,
  PLATFORM_EMBED_QUERY,
  sendIdentityUserPickerSelectionChange,
  type IdentityUserPickerUser,
} from '@webonone/platform-embed'
import {
  Alert,
  AlertDescription,
  Button,
  SearchInput,
  ImagePreview,
  ItemList,
  ItemListContent,
  ItemListEmpty,
  ItemListItem,
  itemListRowActiveClassName,
  itemListThumbClassName,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  ContactValueLine,
  Spinner,
  StatusTag,
  cn,
  isStatusTagVariant,
} from '@webonone/ui-kit'
import { useAppSelector } from '@/app/store/hooks'
import { isAllowedParentOrigin } from '@/features/shell/utils/platformConfig'
import { listUsers } from '@/features/users/services/usersApi'
import type { UserPickerRole, UserPickerUser } from '@/features/users/types'

const ALL_ROLES_VALUE = '__all__'
const SEARCH_DEBOUNCE_MS = 300
const PAGE_SIZE = 20

function formatRoleLabel(role: string): string {
  return role
    .split('_')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ')
}

function toPickerUser(user: UserPickerUser): IdentityUserPickerUser {
  return {
    id: user.id,
    displayName: user.displayName,
    email: user.email ?? '',
    role: user.role,
    avatarUrl: user.avatarUrl,
  }
}

function fromIdentityPickerUser(user: IdentityUserPickerUser): UserPickerUser {
  const role =
    user.role === 'super_admin' || user.role === 'company_admin' || user.role === 'member'
      ? user.role
      : undefined
  return {
    id: user.id,
    displayName: user.displayName,
    email: user.email,
    role,
    avatarUrl: user.avatarUrl ?? null,
  }
}

export function UserPickerPage() {
  const { t } = useTranslation('users')
  const [searchParams] = useSearchParams()
  const accessToken = useAppSelector((state) => state.auth.accessToken)
  const parentOrigin = getPlatformEmbedParentOrigin(searchParams, isAllowedParentOrigin)
  const isEmbed = searchParams.get(PLATFORM_EMBED_QUERY.EMBED) === PLATFORM_EMBED_QUERY.EMBED_VALUE
  const scope = (searchParams.get(PLATFORM_EMBED_QUERY.SCOPE) ?? '').trim()
  const multiple = searchParams.get(PLATFORM_EMBED_QUERY.MODE) === 'multiple'
  const isValid = isEmbed && Boolean(parentOrigin) && scope.length > 0
  const canLoadUsers = isValid && Boolean(accessToken)

  const [searchInput, setSearchInput] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [roleFilter, setRoleFilter] = useState<string>(ALL_ROLES_VALUE)
  const [users, setUsers] = useState<UserPickerUser[]>([])
  const [selectedUsers, setSelectedUsers] = useState<UserPickerUser[]>([])
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(false)
  const [initialLoading, setInitialLoading] = useState(false)
  const [loadingMore, setLoadingMore] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const scrollRootRef = useRef<HTMLDivElement>(null)
  const sentinelRef = useRef<HTMLDivElement>(null)
  const requestIdRef = useRef(0)
  const loadingRef = useRef(false)

  const selectedRole = useMemo(
    () => (roleFilter === ALL_ROLES_VALUE ? null : (roleFilter as UserPickerRole)),
    [roleFilter],
  )

  const selectedUserIds = useMemo(
    () => new Set(selectedUsers.map((user) => user.id)),
    [selectedUsers],
  )

  const notifySelectionChange = useCallback(
    (nextSelectedUsers: UserPickerUser[]) => {
      if (!parentOrigin || !scope) {
        return
      }
      sendIdentityUserPickerSelectionChange(
        parentOrigin,
        scope,
        nextSelectedUsers.map(toPickerUser),
      )
    },
    [parentOrigin, scope],
  )

  useEffect(() => {
    if (!parentOrigin || !scope) {
      return
    }

    function handleMessage(event: MessageEvent) {
      if (event.origin !== parentOrigin) {
        return
      }
      if (!isIdentityUserPickerSetSelectionMessage(event.data) || event.data.scope !== scope) {
        return
      }

      const nextSelectedUsers = multiple
        ? event.data.users.map(fromIdentityPickerUser)
        : event.data.users.slice(0, 1).map(fromIdentityPickerUser)

      setSelectedUsers(nextSelectedUsers)
      notifySelectionChange(nextSelectedUsers)
    }

    window.addEventListener('message', handleMessage)
    return () => window.removeEventListener('message', handleMessage)
  }, [multiple, notifySelectionChange, parentOrigin, scope])

  const fetchPage = useCallback(
    async (targetPage: number, replace: boolean) => {
      if (!canLoadUsers || loadingRef.current) {
        return
      }
      loadingRef.current = true
      const requestId = ++requestIdRef.current
      const isFirstPage = targetPage === 1

      if (isFirstPage) {
        setInitialLoading(true)
      } else {
        setLoadingMore(true)
      }
      setError(null)

      try {
        const response = await listUsers({
          search: debouncedSearch,
          role: selectedRole,
          page: targetPage,
          pageSize: PAGE_SIZE,
        })
        if (requestId !== requestIdRef.current) {
          return
        }

        setUsers((prev) => (replace ? response.items : [...prev, ...response.items]))
        setPage(targetPage)
        setHasMore(targetPage * response.pageSize < response.total)
      } catch (err) {
        if (requestId !== requestIdRef.current) {
          return
        }
        setError(err instanceof Error ? err.message : t('errors.loadUsersFailed'))
        if (replace) {
          setUsers([])
          setHasMore(false)
        }
      } finally {
        loadingRef.current = false
        if (requestId === requestIdRef.current) {
          setInitialLoading(false)
          setLoadingMore(false)
        }
      }
    },
    [canLoadUsers, debouncedSearch, selectedRole],
  )

  useEffect(() => {
    if (!canLoadUsers) {
      return
    }
    const timer = window.setTimeout(() => {
      setDebouncedSearch(searchInput.trim())
    }, SEARCH_DEBOUNCE_MS)
    return () => window.clearTimeout(timer)
  }, [canLoadUsers, searchInput])

  useEffect(() => {
    if (!canLoadUsers) {
      return
    }
    void fetchPage(1, true)
  }, [canLoadUsers, debouncedSearch, selectedRole, fetchPage])

  useEffect(() => {
    if (!canLoadUsers || !hasMore || initialLoading || loadingMore || error) {
      return
    }

    const root = scrollRootRef.current
    const sentinel = sentinelRef.current
    if (!root || !sentinel) {
      return
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          void fetchPage(page + 1, false)
        }
      },
      { root, rootMargin: '120px', threshold: 0 },
    )

    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [canLoadUsers, hasMore, initialLoading, loadingMore, error, page, fetchPage])

  function handleUserToggle(user: UserPickerUser) {
    const nextSelectedUsers = multiple
      ? selectedUserIds.has(user.id)
        ? selectedUsers.filter((entry) => entry.id !== user.id)
        : [...selectedUsers, user]
      : [user]

    setSelectedUsers(nextSelectedUsers)
    notifySelectionChange(nextSelectedUsers)
  }

  const visibleUsers = useMemo(() => {
    if (selectedUsers.length === 0) {
      return users
    }
    const listedIds = new Set(users.map((user) => user.id))
    const missingSelected = selectedUsers.filter((user) => !listedIds.has(user.id))
    return missingSelected.length > 0 ? [...missingSelected, ...users] : users
  }, [selectedUsers, users])

  if (!isValid) {
    return (
      <div className="mx-auto flex min-h-[320px] w-full max-w-3xl items-center justify-center p-6">
        <Alert variant="destructive" className="max-w-xl">
          <AlertDescription>
            {t('errors.pickerEmbedOnly')}
          </AlertDescription>
        </Alert>
      </div>
    )
  }

  if (!accessToken) {
    return (
      <div className="flex min-h-[320px] flex-1 flex-col items-center justify-center gap-3 p-6">
        <Spinner size="lg" />
        <p className="text-sm text-muted-foreground">{t('loading.waitingAuth')}</p>
      </div>
    )
  }

  const showEmpty = !initialLoading && !error && users.length === 0 && selectedUsers.length === 0

  return (
    <div className="mx-auto flex min-h-full w-full max-w-4xl flex-1 flex-col p-4 sm:p-6">
      <div className="flex shrink-0 flex-col gap-3 sm:flex-row sm:items-center">
        <SearchInput
          value={searchInput}
          onChange={(event: ChangeEvent<HTMLInputElement>) => setSearchInput(event.target.value)}
          placeholder={t('searchPlaceholderShort')}
          aria-label={t('searchAria')}
          className="flex-1"
        />
        <Select value={roleFilter} onValueChange={setRoleFilter}>
          <SelectTrigger className="w-full sm:w-52" aria-label={t('filterByRoleAria')}>
            <SelectValue placeholder={t('roles.all')} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL_ROLES_VALUE}>{t('roles.all')}</SelectItem>
            <SelectItem value="super_admin">{t('roles.super_admin')}</SelectItem>
            <SelectItem value="company_admin">{t('roles.company_admin')}</SelectItem>
            <SelectItem value="member">{t('roles.member')}</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div
        ref={scrollRootRef}
        className="mt-4 min-h-[320px] flex-1 overflow-y-auto overscroll-y-contain scrollbar-themed"
      >
        {error ? (
          <Alert variant="destructive" className="mb-4">
            <AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <span>{error}</span>
              <Button variant="outline" size="sm" onClick={() => void fetchPage(1, true)}>
                {t('common:retry')}
              </Button>
            </AlertDescription>
          </Alert>
        ) : null}

        {initialLoading ? (
          <div className="flex items-center justify-center py-12">
            <Spinner size="lg" />
          </div>
        ) : null}

        {showEmpty ? <ItemListEmpty>{t('empty.noneFound')}</ItemListEmpty> : null}

        {!initialLoading && visibleUsers.length > 0 ? (
          <ItemList className="py-2">
            {visibleUsers.map((user) => {
              const isSelected = selectedUserIds.has(user.id)
              return (
                <ItemListItem
                  key={user.id}
                  role="button"
                  tabIndex={0}
                  className={cn(
                    'cursor-pointer transition-colors',
                    isSelected && itemListRowActiveClassName,
                  )}
                  aria-label={multiple ? t('picker.toggleAria', { name: user.displayName }) : t('picker.selectAria', { name: user.displayName })}
                  aria-pressed={isSelected}
                  onClick={() => handleUserToggle(user)}
                  onKeyDown={(event: KeyboardEvent<HTMLLIElement>) => {
                    if (event.key === 'Enter' || event.key === ' ') {
                      event.preventDefault()
                      handleUserToggle(user)
                    }
                  }}
                >
                  <ImagePreview
                    src={user.avatarUrl}
                    alt={user.displayName}
                    mode="view"
                    className={itemListThumbClassName}
                  />
                  <ItemListContent>
                    <p className="truncate font-medium">{user.displayName}</p>
                    <div className="mt-0.5 flex flex-wrap items-center gap-1.5">
                      <ContactValueLine
                        kind="email"
                        value={user.email}
                        emptyLabel={t('noEmail')}
                      />
                      {user.email?.trim() ? (
                        <StatusTag
                          className="shrink-0"
                          variant={user.isEmailVerified ? 'verified' : 'unverified'}
                        />
                      ) : null}
                    </div>
                    {user.phoneNumber?.trim() ? (
                      <div className="mt-0.5 flex flex-wrap items-center gap-1.5">
                        <ContactValueLine kind="phone" value={user.phoneNumber} />
                        <StatusTag
                          className="shrink-0"
                          variant={user.isPhoneVerified ? 'verified' : 'unverified'}
                        />
                      </div>
                    ) : null}
                  </ItemListContent>
                  {user.role ? (
                    isStatusTagVariant(user.role) ? (
                      <StatusTag className="shrink-0 self-center" variant={user.role} />
                    ) : (
                      <StatusTag className="shrink-0 self-center" variant="member">
                        {formatRoleLabel(user.role)}
                      </StatusTag>
                    )
                  ) : null}
                  {isSelected ? (
                    <Check
                      className="ml-auto h-5 w-5 shrink-0 self-center text-primary"
                      aria-hidden
                    />
                  ) : null}
                </ItemListItem>
              )
            })}
          </ItemList>
        ) : null}

        {loadingMore ? (
          <div className="flex justify-center py-3">
            <Spinner size="sm" />
          </div>
        ) : null}

        <div ref={sentinelRef} className="h-1" aria-hidden />
      </div>
    </div>
  )
}
